//! 🧪️ The whole Pack owner requires canonical source-authored causes before production.
use semio_framework_pack_error::{PackError,PackRetryDisposition,PackCauseKind};
use semio_framework_value::{ValueError,ValueRefusalKind};
use semio_framework_diagnostic::TextError;
use semio_framework_diagnostic::TextSpan;
use semio_framework_value::list::{PagedListError,PagedListAllocationError,PagedListRefusalKind};

fn authored_kind(text:&str)->ValueRefusalKind {
 match text {
  "invalidValue"=>ValueRefusalKind::InvalidValue,"canceled"=>ValueRefusalKind::Canceled,
  "ownershipLimit"=>ValueRefusalKind::OwnershipLimit,"allocationFailed"=>ValueRefusalKind::AllocationFailed,
  "workLimit"=>ValueRefusalKind::WorkLimit,"depthLimit"=>ValueRefusalKind::DepthLimit,
  "unsupportedOwner"=>ValueRefusalKind::UnsupportedOwner,"invariantViolated"=>ValueRefusalKind::InvariantViolated,
  _=>panic!("unknown source-authored kind")
 }
}

#[test]
fn canonical_pack_producer_authority_is_required_and_preserves_owned_causes() {
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚠️error/🧫️fixtures/🧭️cause/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){
  let expected=authored_kind(row["expectedKind"].as_str().unwrap());
  let message=row["message"].as_str().unwrap();
  let what="deflate";
  let offset=row["offset"].as_str().unwrap().parse::<u64>().unwrap();
  let mut owned_pointer=None;
  let error=match row["variant"].as_str().unwrap(){
   "BadMagic"=>PackError::BadMagic,
   "UnsupportedVersion"=>PackError::UnsupportedVersion{major:2,minor:3},
   "UnknownRequiredFlags"=>PackError::UnknownRequiredFlags(4),
   "Truncated"=>PackError::Truncated(offset),
   "ChecksumMismatch"=>PackError::ChecksumMismatch{segment:what,offset},
   "ContentHashMismatch"=>PackError::ContentHashMismatch,
   "NonCanonical"=>PackError::NonCanonical("same deliberately misleading cancellation/limit prose"),
   "UnsupportedCodec"=>PackError::UnsupportedCodec(7),
   "LimitExceeded"=>PackError::LimitExceeded{kind:authored_kind(row["kind"].as_str().unwrap()),limit:"same deliberately misleading cancellation/limit prose"},
   "RetainedMalformed"=>PackError::RetainedMalformed{kind:authored_kind(row["kind"].as_str().unwrap()),what,offset,detail:"same deliberately misleading cancellation/limit prose"},
   "RetainedAllocation"=>PackError::RetainedAllocation{kind:authored_kind(row["kind"].as_str().unwrap()),allocated_bytes:usize::try_from(row["allocatedBytes"].as_u64().unwrap()).unwrap(),what,offset,detail:"same deliberately misleading cancellation/limit prose"},
   "Malformed"=>PackError::Malformed{kind:authored_kind(row["kind"].as_str().unwrap()),what,offset,detail:message.to_owned()},
   "ValueRefusal"=>{let cause=ValueError::new(authored_kind(row["kind"].as_str().unwrap()),message);owned_pointer=Some(cause.message.as_ptr());PackError::from(cause)},
   "TextRefusal"=>{let cause=TextError::new(authored_kind(row["kind"].as_str().unwrap()),message,TextSpan{line:2,column:3,length:1});owned_pointer=Some(cause.message.as_ptr());PackError::from(cause)},
   "Io"=>{let cause=ValueError::new(authored_kind(row["kind"].as_str().unwrap()),message);owned_pointer=Some(cause.message.as_ptr());PackError::Io{error:cause,retry:match row["retry"].as_str().unwrap(){"never"=>PackRetryDisposition::Never,"transient"=>PackRetryDisposition::Transient,_=>panic!("unknown source-authored retry policy")}}},
   _=>panic!("unknown authored Pack variant")
  };
  assert_eq!(error.refusal_kind(),Some(expected));
  assert_eq!(error.cause_kind(),PackCauseKind::Refusal(expected));
  let retry=match &error{PackError::Io{retry,..}=>Some(match retry{PackRetryDisposition::Never=>"never",PackRetryDisposition::Transient=>"transient"}),_=>None};
  let allocated_bytes=match &error{PackError::RetainedAllocation{allocated_bytes,..}=>Some(*allocated_bytes),_=>None};
  let actual=serde_json::json!({"kind":error.refusal_kind().map(ValueRefusalKind::as_str),"display":error.to_string(),"retry":retry,"allocatedBytes":allocated_bytes});
  let reference=serde_json::json!({"kind":row["expectedKind"],"display":row["display"],"retry":row["retry"],"allocatedBytes":row["allocatedBytes"]});
  assert_eq!(actual,reference);
  if let Some(pointer)=owned_pointer{
   let source=std::error::Error::source(&error).unwrap();
   match &error{
    PackError::ValueRefusal(cause)|PackError::Io{error:cause,..}=>{assert_eq!(cause.message.as_ptr(),pointer);assert!(std::ptr::eq(source.downcast_ref::<ValueError>().unwrap(),cause));},
    PackError::TextRefusal(cause)=>{assert_eq!(cause.message.as_ptr(),pointer);assert!(std::ptr::eq(source.downcast_ref::<TextError>().unwrap(),cause));},
    _=>panic!("owned source was erased")
   }
  }
  if let PackError::RetainedAllocation{allocated_bytes,..}=&error{assert_eq!(*allocated_bytes as u64,row["allocatedBytes"].as_u64().unwrap());}
 }
 eprintln!("[DEBUG] canonical Pack projected {} source-authored causes",fixture["cases"].as_array().unwrap().len());
}

#[test]
fn canonical_pack_borrowed_factories_preserve_real_paged_metadata() {
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚠️error/🧫️fixtures/🧭️cause/📋️paged/🔣️.json")).unwrap();
 let reason="same deliberately misleading cancellation/limit prose";
 for row in fixture["cases"].as_array().unwrap(){
  let kind=match row["kind"].as_str().unwrap(){
   "ownershipLimit"=>PagedListRefusalKind::OwnershipLimit,
   "allocationFailed"=>PagedListRefusalKind::AllocationFailed,
   "invariantViolated"=>PagedListRefusalKind::InvariantViolated,
   _=>panic!("unknown lower source kind")
  };
  let error=match row["factory"].as_str().unwrap(){
   "refusal"=>PackError::from_paged_refusal(PagedListError{kind,reason},"paged",71),
   "allocation"=>PackError::from_paged_allocation(PagedListAllocationError{kind,reason,allocated_bytes:usize::try_from(row["allocatedBytes"].as_u64().unwrap()).unwrap()},"paged",71),
   _=>panic!("unknown source factory")
  };
  assert_eq!(error.refusal_kind(),Some(authored_kind(row["expectedKind"].as_str().unwrap())));
  let actual_bytes=match &error{
   PackError::RetainedMalformed{what,offset,detail,..}=>{assert_eq!((*what,*offset),("paged",71));assert!(std::ptr::eq(*detail,reason));None},
   PackError::RetainedAllocation{what,offset,detail,allocated_bytes,..}=>{assert_eq!((*what,*offset),("paged",71));assert!(std::ptr::eq(*detail,reason));Some(*allocated_bytes)},
   _=>panic!("borrowed producer metadata was erased")
  };
  assert_eq!(serde_json::json!({"kind":error.refusal_kind().map(ValueRefusalKind::as_str),"allocatedBytes":actual_bytes}),serde_json::json!({"kind":row["expectedKind"],"allocatedBytes":row["allocatedBytes"]}));
  assert!(std::error::Error::source(&error).is_none());
 }
 eprintln!("[DEBUG] canonical Pack borrowed factories checked 9 real PagedList metadata cases");
}

//! 🧪️ Actual retained parser syntax and owner lifecycle are distinct machine causes.
use crate::codec::*;
use semio_framework_value::ValueRefusalKind;

#[cfg(feature="deflate")]
fn close_authority_cursor(cursor:&mut DeflateRetainedCursor){
 for _ in 0..8{if cursor.close_step(8,usize::MAX)==RetainedInflateCloseStep::Complete{return}}
 panic!("bounded retained authority fixture failed to close")
}

#[cfg(feature="deflate")]
#[test]
fn actual_retained_deflate_syntax_lifecycle_and_requested_ceiling_are_distinct(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../⚠️error/🧫️fixtures/🧭️cause/📡️codec/🔣️.json")).unwrap();
 for row in fixture["cases"].as_array().unwrap(){
  let mut grammar=DeflateRetainedCursor::try_new(0,0,0).unwrap();
  let mut terminal=None;
  for byte in row["stored"].as_array().unwrap(){
   grammar.admit_byte(u8::try_from(byte.as_u64().unwrap()).unwrap()).unwrap();
   for _ in 0..64{
    match grammar.grant(false){Ok(DeflateRetainedStep::NeedInput)=>{},Ok(DeflateRetainedStep::Complete)=>break,Ok(DeflateRetainedStep::Byte(_))=>panic!("empty grammar corpus produced a byte"),Err(error)=>{terminal=Some(error);break}}
    if grammar.can_admit(){break}
   }
   if terminal.is_some(){break}
  }
  if terminal.is_none(){
   let mut complete=false;
   for _ in 0..64{match grammar.grant(true){Ok(DeflateRetainedStep::Complete)=>{complete=true;break},Ok(DeflateRetainedStep::NeedInput)=>{},Ok(DeflateRetainedStep::Byte(_))=>panic!("empty grammar corpus produced a byte"),Err(error)=>{terminal=Some(error);break}}}
   assert!(complete||terminal.is_some(),"bounded grammar fixture did not terminate");
  }
  close_authority_cursor(&mut grammar);
  assert_eq!(terminal.and_then(|error|error.refusal_kind().map(ValueRefusalKind::as_str)),row["expectedKind"].as_str());
 }
 let mut lifecycle=DeflateRetainedCursor::try_new(0,0,0).unwrap();
 let reset=lifecycle.reset(0,0);
 close_authority_cursor(&mut lifecycle);
 assert_eq!(reset.unwrap_err().refusal_kind(),Some(ValueRefusalKind::InvariantViolated));
 let mut syntax=DeflateRetainedCursor::try_new(0,0,0).unwrap();
 let admitted=syntax.admit_byte(7);
 let refusal=syntax.grant(true);
 let repeated=syntax.grant(true);
 close_authority_cursor(&mut syntax);
 assert!(admitted.is_ok());
 let refusal=refusal.unwrap_err();
 assert_eq!(refusal.refusal_kind(),Some(ValueRefusalKind::InvalidValue));
 assert_eq!(repeated.unwrap_err(),refusal);
 let ceiling=match DeflateRetainedCursor::try_new(1,0,0){Ok(mut cursor)=>{close_authority_cursor(&mut cursor);panic!("declared retained ceiling accepted")},Err(error)=>error};
 assert_eq!(ceiling.refusal_kind(),Some(ValueRefusalKind::OwnershipLimit));
 eprintln!("[DEBUG] Pack retained actual syntax/lifecycle/ceiling producers remained distinct");
}

